const int maxn = 1005; 
const int maxk = 105;

int a[maxn], b[maxn];
long long pref[maxn], wpref[maxn];
long long dp[maxk][maxn];

static const int BUFSZ = 1 << 20;
static char buf[BUFSZ];
static int buf_pos = 0, buf_len = 0;

inline int readChar() {
    if (buf_pos == buf_len) {
        buf_pos = 0;
        buf_len = fread(buf, 1, BUFSZ, stdin);
        if (!buf_len) return EOF;
    }
    return buf[buf_pos++];
}

inline int readInt() {
    int c = readChar(), x = 0;
    while (c <= ' ') {
        if (c == EOF) return 0;
        c = readChar();
    }
    for (; c >= '0' && c <= '9'; c = readChar())
        x = x * 10 + (c & 15);
    return x;
}

inline long long calc(int p, int j) {
    long long sum = pref[j] - pref[p];
    long long wsum = wpref[j] - wpref[p];
    return wsum - 1LL * p * sum;
}
void recur(int k_, int l, int r, int optl, int optr) {
    if (l > r) return;

    int mid = (l + r) / 2;
    int best_p = -1;
    dp[k_][mid] = 1e18;

    for (int p = optl; p <= min(mid - 1, optr); p++) {
        if (dp[k_ - 1][p] == 1e18) continue;
        long long cur_cost = dp[k_ - 1][p] + calc(p, mid);
        if (cur_cost < dp[k_][mid]) {
            dp[k_][mid] = cur_cost;
            best_p = p;
        }
    }

    if (best_p != -1) {
        recur(k_, l, mid - 1, optl, best_p);
        recur(k_, mid + 1, r, best_p, optr);
    }
}

int main() {
    freopen("cbarn.in", "r", stdin);
    freopen("cbarn.out", "w", stdout);

    int n = readInt();
    int k = readInt();

    for (int i = 0; i < n; i++) a[i] = readInt();

    long long ans = 1e18;

    for (int st = 0; st < n; st++) {
        for (int i = 0; i < n; i++)
            b[i] = a[(st + i) % n];

        pref[0] = wpref[0] = 0;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + b[i];
            wpref[i + 1] = wpref[i] + 1LL * i * b[i];
        }

        for (int j = 0; j <= n; j++) dp[0][j] = 1e18;
        dp[0][0] = 0;

        for (int i = 1; i <= k; i++) {
            for (int j = 0; j <= n; j++) dp[i][j] = 1e18;
            recur(i, i, n, i - 1, n - 1);
        }

        ans = min(ans, dp[k][n]);
    }

    cout << ans;
}